	private static void cooking(BootstrapContext<ContextIntProvider> pBootstrapContext, ResourceKey<ContextIntProvider> pContextIntProvider, int pTime) {
		var contextIntProviders = pBootstrapContext.lookup(Registries.CONTEXT_INT_PROVIDER);
		var predicates = pBootstrapContext.lookup(Registries.PREDICATE);
		var conditionalValue = new ConditionalValue(predicates.getOrThrow(LootPredicates.FAST_FURNACE), contextIntProviders.getOrThrow(ContextIntProviders.COOKING_FAST_BURN_TIME_REDUCTION_FACTOR), contextIntProviders.getOrThrow(ContextIntProviders.COOKING_NORMAL_BURN_TIME_REDUCTION_FACTOR));
		pBootstrapContext.register(pContextIntProvider, ContextIntProviders.div(ContextIntProviders.exactly(pTime), Holder.direct(conditionalValue)).value());
	}

	public static void compostable(BootstrapContext<ContextIntProvider> pBootstrapContext, ResourceKey<ContextIntProvider> pContextIntProvider, int pChance) {
		pBootstrapContext.register(pContextIntProvider, pChance >= 100 ? new ConstantValue(1) : new NumberDispatcher(List.of(new DispatcherProvider.Case<>(Holder.direct(MatchBlock.blockMatches(pBootstrapContext.lookup(Registries.BLOCK), Blocks.COMPOSTER, StatePropertiesPredicate.Builder.properties().hasProperty(ComposterBlock.LEVEL, 0)).build()), ContextIntProviders.exactly(1))), ContextIntProviders.weighted(WeightedList.<Holder<ContextIntProvider>>builder().add(ContextIntProviders.exactly(0), 100 - pChance).add(ContextIntProviders.exactly(1), pChance).build())));
	}
